From a5dd8f5a5041ee98374a897bf32e53d14bd9a7b4 Mon Sep 17 00:00:00 2001
From: Matthew Auld <matthew.auld@intel.com>
Date: Mon, 6 Mar 2017 23:54:00 +0000
Subject: [PATCH] drm/i915/selftests: don't leak the gem object

For our fake dma objects we can leak the underlying gem object if we
fail to pin our "backing storage".

[   39.952618] =============================================================================
[   39.952625] BUG mock_object (Tainted: G     U         ): Objects remaining in mock_object on __kmem_cache_shutdown()
[   39.952629] 
diff --git a/drivers/gpu/drm/i915/selftests/i915_gem_gtt.c b/drivers/gpu/drm/i915/selftests/i915_gem_gtt.c
index 0f3fa34377c6..c4a39b7d7dd0 100644
--- a/drivers/gpu/drm/i915/selftests/i915_gem_gtt.c
+++ b/drivers/gpu/drm/i915/selftests/i915_gem_gtt.c
@@ -103,7 +103,7 @@ fake_dma_object(struct drm_i915_private *i915, u64 size)

 	obj = i915_gem_object_alloc(i915);
 	if (!obj)
-		return ERR_PTR(-ENOMEM);
+		goto err;

 	drm_gem_private_object_init(&i915->drm, &obj->base, size);
 	i915_gem_object_init(obj, &fake_ops);
@@ -114,10 +114,15 @@ fake_dma_object(struct drm_i915_private *i915, u64 size)

 	/* Preallocate the "backing storage" */
 	if (i915_gem_object_pin_pages(obj))
-		return ERR_PTR(-ENOMEM);
+		goto err_obj;

 	i915_gem_object_unpin_pages(obj);
 	return obj;
+
+err_obj:
+	i915_gem_object_put(obj);
+err:
+	return ERR_PTR(-ENOMEM);
 }

 static int igt_ppgtt_alloc(void *arg)
-- 
2.25.1

Code statements:
```c
	obj = i915_gem_object_alloc(i915);
	if (!obj)
		goto err;

	if (i915_gem_object_pin_pages(obj))
		goto err_obj;

err_obj:
	i915_gem_object_put(obj);
err:
	return ERR_PTR(-ENOMEM);
```

Code statements:
```c
obj = i915_gem_object_alloc(i915);
if (!obj)
    goto err;

if (i915_gem_object_pin_pages(obj))
    goto err_obj;

i915_gem_object_put(obj);
err:
return ERR_PTR(-ENOMEM);
```

You are a programming expert.

You will be given details about a bug, including:
1. The root cause.
2. Code statements that lead to the bug and the reason for it.
3. Code statements that fix the bug and the reason for the fix.

Based on these details, your task is to determine whether the provided code snippet contains the bug.
Think step by step.
Be conservative in your assessment. If you are unsure, answer "no."

Root cause:
The bug is caused by the failure to properly release the underlying gem object when the allocation or pinning of the backing storage fails in the `fake_dma_object` function. This can lead to memory leaks, as the allocated gem object remains unfreed if an error occurs after its creation but before it is successfully pinned.

Code statements information:
The code statements that lead to the bug are:
```c
obj = i915_gem_object_alloc(i915);
if (!obj)
    return ERR_PTR(-ENOMEM);
```
Reason:
The bug occurs because if the allocation of the `obj` (the gem object) fails after it has been created but before it is successfully pinned, the code does not properly release the allocated gem object, leading to a memory leak.

The code statements that fix the bug are:
```c
goto err;
...
err_obj:
    i915_gem_object_put(obj);
```
Reason:
The patch introduces error handling that ensures if the pinning of the backing storage fails, the code jumps to the `err_obj` label, where it calls `i915_gem_object_put(obj)` to properly release the allocated gem object, thus preventing memory leaks.


Now, determine whether the provided code snippet is buggy:

	obj = i915_gem_object_alloc(i915);
	if (!obj)
		return ERR_PTR(-ENOMEM);

	drm_gem_private_object_init(&i915->drm, &obj->base, size);
	i915_gem_object_init(obj, &fake_ops);

	obj->base.write_domain = I915_GEM_DOMAIN_CPU;
	obj->base.read_domains = I915_GEM_DOMAIN_CPU;
	obj->cache_level = I915_CACHE_NONE;

	/* Preallocate the "backing storage" */
	if (i915_gem_object_pin_pages(obj))
		return ERR_PTR(-ENOMEM);

	i915_gem_object_unpin_pages(obj);
	return obj;
}

